<?php
session_start();require_once '../shared/config.php';
require_once '../shared/security.php';
o2oCsrfToken();requireLogin('customer','login.php');$db=getDB();$customerId=(int)$_SESSION['customer_id'];$itemId=(int)($_GET['item_id']??$_POST['item_id']??0);$message='';$error='';
$st=$db->prepare("SELECT i.id,i.name,i.category,i.quality FROM items i WHERE i.id=? AND i.available=1");$st->execute([$itemId]);$item=$st->fetch();
if(!$item){header('Location: home.php');exit;}
$st=$db->prepare("SELECT * FROM size_profiles WHERE customer_id=? LIMIT 1");$st->execute([$customerId]);$profile=$st->fetch();
$st=$db->prepare("SELECT * FROM product_sizes WHERE item_id=? AND available=1 ORDER BY size_label");$st->execute([$itemId]);$sizes=$st->fetchAll();
$recommendation=null;$fitDifference=null;$fitCoverage=0;$fitGuidance='';
if($profile&&$sizes){
 $best=null;$bestDiff=PHP_INT_MAX;
 foreach($sizes as $s){$diff=0;$used=false;foreach(['chest','waist','hip'] as $m){if($profile[$m]!==null&&$s[$m]!==null&&$s[$m]>0){$diff+=abs((float)$profile[$m]-(float)$s[$m]);$used=true;}}if($used&&$diff<$bestDiff){$bestDiff=$diff;$best=$s;}}
 if($best){$recommendation=$best;$fitDifference=$bestDiff;$fitCoverage=0;foreach(['chest','waist','hip'] as $m){if($profile[$m]!==null&&$best[$m]!==null&&$best[$m]>0)$fitCoverage++;}$fitGuidance=$fitCoverage>=3?'Strongest match across chest, waist and hip.':($fitCoverage===2?'Match based on two shared measurements.':'Limited match based on one shared measurement.');}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save_size'){o2oRequireCsrf();
 $vals=[];foreach(['height','chest','waist','hip','shoulder','sleeve'] as $k)$vals[$k]=(float)($_POST[$k]??0);
 $shoe=trim($_POST['shoe_size']??'');$st=$db->prepare("INSERT INTO size_profiles(customer_id,height,chest,waist,hip,shoulder,sleeve,shoe_size) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE height=VALUES(height),chest=VALUES(chest),waist=VALUES(waist),hip=VALUES(hip),shoulder=VALUES(shoulder),sleeve=VALUES(sleeve),shoe_size=VALUES(shoe_size)");$st->execute([$customerId,$vals['height']?:null,$vals['chest']?:null,$vals['waist']?:null,$vals['hip']?:null,$vals['shoulder']?:null,$vals['sleeve']?:null,$shoe?:null]);header('Location: fit.php?item_id='.$itemId);exit;
}
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Fit Guidance – O2O Tradition</title><style>
body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:18px 28px}.nav a{color:#E8CC82;margin-left:18px;text-decoration:none}.main{max-width:850px;margin:auto;padding:30px}.hero,.card{background:#fff;border:1px solid #E8E0D0;padding:24px;margin-bottom:18px}.hero{background:#28170c;color:#fff}.size{font-size:30px;color:#8B1A1A}.good{background:#ECFDF5;padding:14px;color:#065F46}.warn{background:#FEF3C7;padding:14px;color:#92400E}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.input{width:100%;padding:10px;box-sizing:border-box}.btn{padding:12px 18px;background:#1A1108;color:#C9A84C;border:0;margin-top:14px}.small{font-size:12px;color:#777;line-height:1.6}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="nav"><b>O2O Tradition</b><a href="item.php?id=<?=$itemId?>">← Back to Item</a><a href="size_profile.php">Size Profile</a></div><main class="main"><section class="hero"><h1>📏 AI Size & Fit Guidance</h1><p>Fit guidance for <b><?=htmlspecialchars($item['name'])?></b>. The recommendation uses your saved measurements and the vendor's available size measurements when both are present.</p></section><?php if(!$profile):?><section class="card"><h2>Save your measurements</h2><form method="POST">\n<input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="save_size"><div class="grid"><?php foreach(['height','chest','waist','hip','shoulder','sleeve'] as $k):?><div><label><?=ucfirst($k)?> (cm)</label><input class="input" type="number" step="0.1" min="0" name="<?=$k?>"></div><?php endforeach;?><div><label>Shoe size</label><input class="input" name="shoe_size"></div></div><button class="btn">Save & Check Fit</button></form></section><?php elseif(!$sizes):?><section class="card warn"><b>No vendor size measurements are available for this item yet.</b><p class="small">Your profile is saved, but O2O Tradition cannot responsibly calculate a product-specific fit without the item's measurements.</p></section><?php elseif(!$recommendation):?><section class="card warn"><b>Fit guidance is unavailable.</b><p class="small">There is not enough overlapping measurement data between your profile and this item's size chart.</p></section><?php else:?><?php $label=$recommendation['size_label'];?><section class="card"><div class="size">Suggested size: <?=htmlspecialchars($label)?></div><div class="good"><b>Measurement-based match.</b><br><?=htmlspecialchars($fitGuidance)?> This is a comparison against the available item measurements, not a guarantee of fit.</div><p class="small">Combined measurement difference: <?=number_format((float)$fitDifference,1)?> cm across <?=$fitCoverage?> shared measurement<?=($fitCoverage===1?'':'s')?>. Smaller differences indicate a closer measurement match, but garment cut and fabric can change the actual fit.</p><p class="small">Your profile is compared using available chest, waist and hip measurements. Differences can vary by garment cut, fabric and how measurements were taken.</p></section><section class="card"><h3>Available item sizes</h3><?php foreach($sizes as $s):?><div style="padding:9px 0;border-bottom:1px solid #eee"><b><?=htmlspecialchars($s['size_label'])?></b> · Chest <?=htmlspecialchars($s['chest']??'—')?> · Waist <?=htmlspecialchars($s['waist']??'—')?> · Hip <?=htmlspecialchars($s['hip']??'—')?> · Length <?=htmlspecialchars($s['length']??'—')?> cm</div><?php endforeach;?></section><?php endif;?></main></body></html>